import json
from typing import Any


def format_table(rows: list[tuple], headers: tuple[str, ...]) -> str:
    """Render a text table with aligned columns from rows and headers.

    Columns are sized to the widest cell (header or row value).  Numeric-looking
    cells (those that parse as ``float``) are right-aligned; all others are
    left-aligned.  A dash separator separates the header row from the body.
    Returns a string with a trailing newline.
    """
    if not headers:
        return "\n"

    # Normalise rows: replace None with empty string, convert to str for width calc
    def _cell_str(val: Any) -> str:
        return "" if val is None else str(val)

    all_rows = [_cell_str(v) for v in headers] + [
        [_cell_str(v) for v in row] for row in rows
    ]

    # Compute column widths
    num_cols = len(headers)
    col_widths: list[int] = [0] * num_cols
    for row_vals in all_rows:
        for i, val in enumerate(row_vals):
            if i < num_cols:
                col_widths[i] = max(col_widths[i], len(val))

    def _is_numeric(s: str) -> bool:
        try:
            float(s)
            return True
        except (ValueError, TypeError):
            return False

    def _format_row(values: list[str]) -> str:
        parts = []
        for i, val in enumerate(values):
            if i >= num_cols:
                break
            w = col_widths[i]
            if _is_numeric(val) and val != "":
                parts.append(val.rjust(w))
            else:
                parts.append(val.ljust(w))
        return " ".join(parts)

    lines: list[str] = []
    header_vals = [_cell_str(v) for v in headers]
    lines.append(_format_row(header_vals))
    lines.append(" ".join("-" * w for w in col_widths))
    for row in rows:
        row_vals = [_cell_str(v) for v in row]
        lines.append(_format_row(row_vals))

    return "\n".join(lines) + "\n"


def format_json(data: Any) -> str:
    """Serialize data to an indented JSON string with trailing newline."""
    return json.dumps(data, indent=2) + "\n"
